document.addEventListener('DOMContentLoaded',function (){var topBar=document.getElementById('topBar');var header=document.getElementById('siteHeader');var hamburger=document.getElementById('hamburger');var mobileNav=document.getElementById('mobileNav');window.addEventListener('scroll',function (){var scrollY=window.scrollY||window.pageYOffset;if (scrollY>50){header.classList.add('scrolled');} else {header.classList.remove('scrolled');}if (window.innerWidth>1024){if (scrollY>100){topBar.classList.add('hidden');} else {topBar.classList.remove('hidden');}}},{passive: true});if (hamburger&&mobileNav){hamburger.addEventListener('click',function (){hamburger.classList.toggle('active');mobileNav.classList.toggle('active');document.body.style.overflow=mobileNav.classList.contains('active')? 'hidden' : '';});}document.querySelectorAll('.mobile-nav-link[data-toggle]').forEach(function (link){link.addEventListener('click',function (e){e.preventDefault();var targetId=this.getAttribute('data-toggle');var target=document.getElementById(targetId);if (target){document.querySelectorAll('.mobile-subnav.open').forEach(function (el){if (el.id!==targetId){el.classList.remove('open');var pl=document.querySelector('[data-toggle="'+el.id+'"]');if (pl)pl.classList.remove('open');}});target.classList.toggle('open');this.classList.toggle('open');}});});if (mobileNav){mobileNav.querySelectorAll('a:not([data-toggle])').forEach(function (link){link.addEventListener('click',function (){hamburger.classList.remove('active');mobileNav.classList.remove('active');document.body.style.overflow='';});});}window.addEventListener('resize',function (){if (window.innerWidth>1024&&mobileNav&&mobileNav.classList.contains('active')){hamburger.classList.remove('active');mobileNav.classList.remove('active');document.body.style.overflow='';}});var catLinks=document.querySelectorAll('.mega-cat-link[data-panel]');var panels=document.querySelectorAll('.mega-sub-panel');var defaultMsg=document.querySelector('.mega-default-msg');catLinks.forEach(function (link){link.addEventListener('mouseenter',function (){var panelId=this.getAttribute('data-panel');var panel=document.getElementById(panelId);if (defaultMsg)defaultMsg.style.display='none';panels.forEach(function (p){p.classList.remove('active-panel');});catLinks.forEach(function (cl){cl.classList.remove('active-cat');});if (panel)panel.classList.add('active-panel');this.classList.add('active-cat');});});var megaProduse=document.getElementById('megaProduse');if (megaProduse){megaProduse.addEventListener('mouseleave',function (){panels.forEach(function (p){p.classList.remove('active-panel');});catLinks.forEach(function (cl){cl.classList.remove('active-cat');});if (defaultMsg)defaultMsg.style.display='';});}});